<?php
namespace AmazingPlugins\Security\Tests\Unit\Digest;
use AmazingPlugins\Security\Integrity\OptionGateway;
final class MemoryOptions implements OptionGateway {
 public array $values=[]; public bool $failWrites=false; public bool $failStateWrites=false; public bool $failContentWrites=false; public bool $failRepositoryWrites=false; public bool $failExposureWrites=false; public bool $failHeaderWrites=false; public bool $failRestRateWrites=false; public bool $failNetworkWrites=false;
 public function get(string $key):mixed{return $this->values[$key]??null;}
 public function add(string $key,string $value):bool{if($this->failWrites||($this->failStateWrites&&$key==='ironlatch_digest_state')||($this->failContentWrites&&$key==='ironlatch_content_state')||($this->failRepositoryWrites&&$key==='ironlatch_repository_state')||($this->failExposureWrites&&$key==='ironlatch_exposure_state')||($this->failHeaderWrites&&$key==='ironlatch_headers_state')||($this->failRestRateWrites&&$key==='ironlatch_rest_rate_policy')||($this->failNetworkWrites&&in_array($key,['ironlatch_network_policy','ironlatch_network_observation'],true))||isset($this->values[$key]))return false;$this->values[$key]=$value;return true;}
 public function set(string $key,string $value):bool{if($this->failWrites)return false;$this->values[$key]=$value;return true;}
 public function delete(string $key):void{unset($this->values[$key]);}
 public function replaceIfSame(string $key,string $expected,string $replacement):bool{if($this->failWrites||($this->failStateWrites&&$key==='ironlatch_digest_state')||($this->failContentWrites&&$key==='ironlatch_content_state')||($this->failRepositoryWrites&&$key==='ironlatch_repository_state')||($this->failExposureWrites&&$key==='ironlatch_exposure_state')||($this->failHeaderWrites&&$key==='ironlatch_headers_state')||($this->failRestRateWrites&&$key==='ironlatch_rest_rate_policy')||($this->failNetworkWrites&&in_array($key,['ironlatch_network_policy','ironlatch_network_observation'],true))||($this->values[$key]??null)!==$expected)return false;$this->values[$key]=$replacement;return true;}
 public function deleteIfSame(string $key,string $expected):bool{if($this->failWrites||($this->failStateWrites&&$key==='ironlatch_digest_state')||($this->failContentWrites&&$key==='ironlatch_content_state')||($this->failRepositoryWrites&&$key==='ironlatch_repository_state')||($this->failExposureWrites&&$key==='ironlatch_exposure_state')||($this->failHeaderWrites&&$key==='ironlatch_headers_state')||($this->failRestRateWrites&&$key==='ironlatch_rest_rate_policy')||($this->failNetworkWrites&&in_array($key,['ironlatch_network_policy','ironlatch_network_observation'],true))||($this->values[$key]??null)!==$expected)return false;unset($this->values[$key]);return true;}
}
